nodes = {"node-a": 4, "node-b": 2, "node-c": 6}
pods = [("web-1", 2), ("web-2", 3), ("cache-1", 1)]


def schedule(nodes, cpu_request):
    candidates = [n for n, avail in nodes.items() if avail >= cpu_request]
    if not candidates:
        return None
    return max(candidates, key=lambda n: nodes[n])


for pod_name, cpu in pods:
    node = schedule(nodes, cpu)
    if node:
        nodes[node] -= cpu
        print(f"{pod_name} -> {node} (cpu restante: {nodes[node]})")
    else:
        print(f"{pod_name} -> sin nodo disponible")
